    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>logistic regression রৈখিক সীমানা টানে। বৃত্তাকার সীমানার ডেটায় সে কতটা পারবে? একটি ছোট নেটওয়ার্ক কি পারবে—এবং আপনি কি প্রমাণ করতে পারবেন যে নেটওয়ার্কের ভেতরে ঠিক সেই হিসাবগুলোই হচ্ছে যা শিখেছেন?</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>একটি নেটওয়ার্কের এক training ধাপ সম্পূর্ণ ট্রেস করে হাতের হিসাবের সাথে মেলাতে পারবেন</li><li>held-out test সেটে neural network ও logistic regression তুলনা করতে পারবেন</li><li>শেখা সীমানা দৃশ্যমান করে মডেলের সীমা ব্যাখ্যা করতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 70 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/normalization-residual-dropout/">Normalization, Residual ও Dropout</a></li><li><a href="/ai-academy/lesson/train-validation-test/">Train, Validation ও Test Split</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>ডেটা (সিন্থেটিক):</strong> x, y ∈ [−১, ১] দৈব; লেবেল = ১ যদি x² + y² < ০.৫ (বৃত্তের ক্ষেত্রফল ≈ π × ০.৫ ≈ ১.৫৭, বর্গক্ষেত্র ৪, তাই প্রায় ৩৯% বিন্দু ভেতরে)। seed-যুক্ত, ১৬০টি train, ৮০টি test।</p><p><strong>মডেল:</strong> ২→৮→১, tanh hidden, sigmoid output, binary cross-entropy, full-batch gradient descent, η = ০.৫, ৮০০ epoch। weight দৈব [−১, ১]।</p><p><strong>তুলনার ভিত্তি:</strong> একই ডেটায় logistic regression (hidden নেই)। “সবসময় ০” মডেলের accuracy-ও লিখব (এই seed-এর test সেটে ০.৫৯)—যেকোনো মডেলকে এটি অবশ্যই ছাড়াতে হবে।</p><p><strong>ট্রেস:</strong> প্রথম ধাপে প্রথম উদাহরণের জন্য z₁, h, ŷ, loss, δ₂, δ₁ এবং পুরো batch-এর গড় gradient দিয়ে W₂[০]-এর আপডেট আগে-পরে।</p><div class="wgba-note wgba-note-warn">ফলটি একটি নির্দিষ্ট seed ও সিন্থেটিক ডেটার। এটি দেখায় নেটওয়ার্ক বাঁকা সীমানা শিখতে <em>পারে</em>; কোনো বাস্তব সমস্যায় কার্যকারিতা প্রমাণ করে না।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> ট্রেস হলো রান্নার প্রতিটি ধাপে স্বাদ নেওয়া: শেষ খাবার খারাপ হলে কোন ধাপে লবণ বেশি পড়েছে বোঝা যায়।</p><p><strong>কোথায় ভাঙে:</strong> রান্নায় ধাপ কয়েকটি; নেটওয়ার্কে হাজার ধাপ, সব ট্রেস করা অসম্ভব। তাই প্রথম ধাপ ও কয়েকটি সারাংশ-সংখ্যা (loss বক্ররেখা, accuracy) দেখা হয়।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>ASCII decision map পড়ার নিয়ম: ২১×১১ গ্রিড, প্রতিটি ঘরে মডেলের p। “#” মানে p ≥ ০.৫ (ভেতরে), “.” মানে বাইরে। সঠিক মডেলে মাঝে একটি মোটামুটি গোলাকার “#” দাগ দেখা উচিত। x-অক্ষে ঘর বেশি কারণ টেক্সট অক্ষর লম্বাটে।</p></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><p><strong>প্রজেক্ট মানদণ্ড:</strong> (১) প্রথম ধাপের ট্রেসের δ₂ = ŷ − y হাতে মেলান, (২) neural network, logistic regression ও “সব ০”-এর test accuracy টেবিল, (৩) decision map-এ কোথায় ভুল হচ্ছে চিহ্নিত করুন, (৪) hidden = ২ দিয়ে আবার চালিয়ে পার্থক্য লিখুন।</p><h3>প্রজেক্ট: বৃত্ত-classifier, ট্রেস ও decision map</h3><div class="wgba-playground-slot" data-exercise="ex-les-05-07-project-tiny-network-1"><pre class="wgba-code"><code>function makeRng(seed) {
  let a = seed &gt;&gt;&gt; 0;
  return function () {
    a = (a + 0x6D2B79F5) &gt;&gt;&gt; 0;
    let t = a;
    t = Math.imul(t ^ (t &gt;&gt;&gt; 15), t | 1);
    t ^= t + Math.imul(t ^ (t &gt;&gt;&gt; 7), t | 61);
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}

const rand = makeRng(77);
const gen = (n) =&gt; Array.from({ length: n }, () =&gt; { const x = [rand() * 2 - 1, rand() * 2 - 1]; return { x, y: x[0] ** 2 + x[1] ** 2 &lt; 0.5 ? 1 : 0 }; });
const train = gen(160), test = gen(80);
const sigmoid = (z) =&gt; 1 / (1 + Math.exp(-z));
const r3 = (v) =&gt; Math.round(v * 1000) / 1000;

function makeNet(H, seed) {
  const r = makeRng(seed), u = () =&gt; r() * 2 - 1;
  return { H, W1: Array.from({ length: H }, () =&gt; [u(), u()]), b1: new Array(H).fill(0), W2: Array.from({ length: H }, u), b2: 0 };
}
function forward(net, x) {
  const z1 = net.W1.map((w, j) =&gt; w[0] * x[0] + w[1] * x[1] + net.b1[j]);
  const h = z1.map(Math.tanh);
  const yhat = sigmoid(h.reduce((s, v, j) =&gt; s + v * net.W2[j], 0) + net.b2);
  return { z1, h, yhat };
}
function step(net, data, lr, trace = false) {
  const H = net.H, gW1 = net.W1.map(() =&gt; [0, 0]), gb1 = new Array(H).fill(0), gW2 = new Array(H).fill(0); let gb2 = 0, L = 0;
  data.forEach((d, n) =&gt; {
    const { z1, h, yhat } = forward(net, d.x);
    L += -(d.y * Math.log(yhat) + (1 - d.y) * Math.log(1 - yhat)) / data.length;
    const d2 = yhat - d.y;
    const d1 = h.map((hj, j) =&gt; d2 * net.W2[j] * (1 - hj * hj));
    if (trace &amp;&amp; n === 0) {
      console.log(&quot;ট্রেস · উদাহরণ ০: x =&quot;, d.x.map(r3), &quot;y =&quot;, d.y);
      console.log(&quot;  z1[0..2] =&quot;, z1.slice(0, 3).map(r3), &quot; h[0..2] =&quot;, h.slice(0, 3).map(r3));
      console.log(&quot;  ŷ =&quot;, r3(yhat), &quot; loss =&quot;, r3(-(d.y * Math.log(yhat) + (1 - d.y) * Math.log(1 - yhat))), &quot; δ2 = ŷ − y =&quot;, r3(d2));
      console.log(&quot;  δ1[0..2] =&quot;, d1.slice(0, 3).map(r3));
    }
    gb2 += d2 / data.length;
    for (let j = 0; j &lt; H; j++) { gW2[j] += d2 * h[j] / data.length; gb1[j] += d1[j] / data.length; gW1[j][0] += d1[j] * d.x[0] / data.length; gW1[j][1] += d1[j] * d.x[1] / data.length; }
  });
  const before = net.W2[0];
  for (let j = 0; j &lt; H; j++) { net.W2[j] -= lr * gW2[j]; net.b1[j] -= lr * gb1[j]; net.W1[j][0] -= lr * gW1[j][0]; net.W1[j][1] -= lr * gW1[j][1]; }
  net.b2 -= lr * gb2;
  if (trace) console.log(&quot;  update: W2[0]&quot;, r3(before), &quot;− &quot; + lr + &quot; ×&quot;, r3(gW2[0]), &quot;=&quot;, r3(net.W2[0]), &quot;| batch loss&quot;, r3(L));
  return L;
}
const accuracy = (f, data) =&gt; data.filter((d) =&gt; (f(d.x) &gt;= 0.5 ? 1 : 0) === d.y).length / data.length;

// ---- neural network ----
const net = makeNet(8, 1);
const losses = [step(net, train, 0.5, true)];
for (let e = 1; e &lt; 800; e++) losses.push(step(net, train, 0.5));
console.log(&quot;loss: epoch 0 =&quot;, r3(losses[0]), &quot;| 100 =&quot;, r3(losses[100]), &quot;| 799 =&quot;, r3(losses[799]));

// ---- logistic regression (hidden নেই) ----
let w = [0, 0], b = 0;
for (let e = 0; e &lt; 800; e++) {
  let g = [0, 0], gb = 0;
  for (const d of train) { const p = sigmoid(w[0] * d.x[0] + w[1] * d.x[1] + b); g[0] += (p - d.y) * d.x[0] / train.length; g[1] += (p - d.y) * d.x[1] / train.length; gb += (p - d.y) / train.length; }
  w = [w[0] - 0.5 * g[0], w[1] - 0.5 * g[1]]; b -= 0.5 * gb;
}
const nnF = (x) =&gt; forward(net, x).yhat, lrF = (x) =&gt; sigmoid(w[0] * x[0] + w[1] * x[1] + b);
const res = { nnTrain: accuracy(nnF, train), nnTest: accuracy(nnF, test), lrTest: accuracy(lrF, test), zeroTest: accuracy(() =&gt; 0, test) };
console.log(&quot;test accuracy → neural net:&quot;, r3(res.nnTest), &quot;| logistic:&quot;, r3(res.lrTest), &quot;| সব 0:&quot;, r3(res.zeroTest), &quot;| (nn train:&quot;, r3(res.nnTrain) + &quot;)&quot;);

// ---- ASCII decision map ----
for (let i = 0; i &lt;= 10; i++) {
  const yy = 1 - i * 0.2; let row = &quot;&quot;;
  for (let k = 0; k &lt;= 20; k++) row += nnF([-1 + k * 0.1, yy]) &gt;= 0.5 ? &quot;#&quot; : &quot;.&quot;;
  console.log(row);
}</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>gen(n)</code>: seed ৭৭ দিয়ে বিন্দু; লেবেল নিয়ম জানা—এটি সিন্থেটিক ডেটার সুবিধা।</li><li><code>step(..., trace)</code>: একই ফাংশন training ও ট্রেস দুই কাজে—ট্রেস করা সংখ্যাগুলোই আসল আপডেটে ব্যবহৃত হয়।</li><li><code>before</code> ও <code>net.W2[0]</code>: update-এর আগে-পরে—অধ্যায় ৩-এর w ← w − η g।</li><li><code>accuracy(() => 0, test)</code>: “সবসময় বাইরে” baseline।</li><li>decision map: প্রতিটি ঘরে forward চালিয়ে p ≥ ০.৫ হলে #।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>ট্রেসটি training কোডের ভেতর থেকে মুদ্রণ করা হয়েছে, আলাদা হিসাব নয়—তাই যা দেখছেন তা-ই মডেল ব্যবহার করছে। baseline (“সব ০” ও logistic regression) ছাড়া neural network-এর accuracy অর্থহীন; ৮৫% শুনতে ভালো, কিন্তু baseline ৮৪% হলে কিছুই শেখা হয়নি।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>প্রথম ধাপের ট্রেস দিয়ে কোড যাচাই</li><li>সবসময় baseline-এর সাথে তুলনা</li><li>held-out test-এ মূল্যায়ন</li><li>decision map মডেলের সীমা দেখায়</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>mini-batch সংস্করণ</li><li>validation দিয়ে early stopping</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>noise যোগ করুন: gen-এ ১০% বিন্দুর লেবেল দৈবভাবে উল্টে দিন (rand() < ০.১ হলে 1 − y)। hidden = ৮ ও ৩২ দিয়ে train ও test accuracy তুলনা করুন। কোনটি overfit করে? অধ্যায় ৪-এর শিক্ষার সাথে মেলান।</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>baseline ছাড়া accuracy রিপোর্ট</li><li>train accuracy-কে test হিসেবে দেখানো</li><li>ট্রেস আলাদা কোডে হিসাব করা (আসল কোডের বাগ লুকিয়ে যায়)</li><li>একটি seed-এর ফলকে সাধারণ সত্য বলা</li></ul></section>
<details class="wgba-disclose"><summary>সমাধান ও ব্যাখ্যা</summary><div><p>প্রত্যাশিত পর্যবেক্ষণ (seed ৭৭ ও ১, QuickJS-এ চালানো): neural network-এর test accuracy প্রায় ১ (৮০টির প্রায় সব); logistic regression ০.৪৪—“সব ০”-এর ০.৫৯-এর চেয়েও কম, কারণ কোনো সরলরেখা বৃত্তের ভেতর-বাইরে আলাদা করতে পারে না। ৮০টি test বিন্দুতে প্রায় ১০০% মানে সব ক্ষেত্রে নিখুঁত নয়—সীমানার খুব কাছের বিন্দু test-এ কম পড়েছে। decision map-এ মাঝে মোটামুটি গোলাকার # অঞ্চল; সীমানার কাছে কয়েকটি ঘর ভুল হওয়া স্বাভাবিক, কারণ ১৬০টি বিন্দুতে সীমানার কাছে উদাহরণ কম।</p></div></details>
<section class="wgba-section" id="check"><h2>জ্ঞান যাচাই</h2><p>নিচের 3টি প্রশ্নের উত্তর দিয়ে “জমা দিন” চাপুন। স্কোর সার্ভারে যাচাই হয়; প্রতিটি উত্তরের পর কেন সঠিক বা ভুল তা দেখাবে। লগইন থাকলে ফল আপনার অগ্রগতিতে সংরক্ষিত হয়।</p></section>
<section class="wgba-section" id="recap"><h2>সংক্ষেপে মনে রাখুন</h2><ul><li>একটি সম্পূর্ণ, ট্রেসযোগ্য neural network বানালেন</li><li>baseline ও held-out test দিয়ে সৎ তুলনা</li><li>বাঁকা সীমানা—hidden layer-এর শক্তি</li></ul></section>
